function testKgPerSqFt() {
  const harvests = [{ bed: "B1", kg: 3.2 }, { bed: "B2", kg: 1.2 }, { bed: "B1", kg: 3.2 }]
  const beds = [{ id: "B1", sizeSqFt: 32 }, { id: "B2", sizeSqFt: 24 }]
  console.log(JSON.stringify(kgPerSqFt(harvests, beds)))
}

function kgPerSqFt(harvests, beds) {
  return beds.map(bed => {
    const total = harvests
      .filter(h => h.bed === bed.id)
      .reduce((sum, h) => sum + h.kg, 0)
    return { bed: bed.id, kgPerSqFt: Math.round(total / bed.sizeSqFt * 100) / 100 }
  })
}
